//! Comments (PDF annotations): listing the ones already in a file, and writing the
//! ones created or changed in the app.
//!
//! Annotations live in the page's `/Annots`, not in its content stream, so nothing
//! here ever asks PDFium to regenerate page content. Appearance streams for new
//! annotations are generated by PDFium when the page is rendered with annotations
//! (see `Page::generate_annot_appearances`).

use std::ffi::{c_int, c_uint};

use pdfium_render::prelude::{FPDF_ANNOTATION, FS_POINTF, FS_QUADPOINTSF, FS_RECTF};

use super::pdf::{Doc, Page, read_utf16, to_wide};
use crate::geometry::Matrix;
use crate::protocol::{
    AnnotChange, AnnotInfo, AnnotShape, MAX_ANNOT_PAGES, MAX_ANNOT_TEXT, NewAnnot, PageAnnots,
    Rect, TextChars,
};

pub const FPDF_ANNOT_TEXT: c_int = 1;
pub const FPDF_ANNOT_HIGHLIGHT: c_int = 9;
pub const FPDF_ANNOT_INK: c_int = 15;
const FPDF_ANNOT_FLAG_INVISIBLE: c_int = 1;
const FPDF_ANNOT_FLAG_HIDDEN: c_int = 2;
pub const FPDF_ANNOT_FLAG_PRINT: c_int = 4;
pub const FPDF_ANNOT_FLAG_NOZOOM: c_int = 8;
pub const FPDF_ANNOT_FLAG_NOROTATE: c_int = 16;
const FPDF_ANNOT_FLAG_NOVIEW: c_int = 32;
const FPDFANNOT_COLORTYPE_COLOR: c_uint = 0;

/// Size of a sticky-note icon, in points.
pub const NOTE_SIZE: f32 = 20.0;
/// Most comments listed per page; the rest are counted in `PageAnnots::more`.
pub const MAX_LISTED_PER_PAGE: usize = 500;
/// Text listed per page and per request, in bytes, so a hostile file cannot make
/// one response huge.
const MAX_PAGE_TEXT_BYTES: usize = 4 * 1024 * 1024;
const MAX_REQUEST_TEXT_BYTES: usize = 8 * 1024 * 1024;
/// Most characters returned by `text_chars`.
pub const MAX_TEXT_CHARS: i32 = 100_000;

/// Subtypes listed as comments. Links, form fields, popups, watermarks and media are not.
const LISTED: &[(c_int, &str)] = &[
    (FPDF_ANNOT_TEXT, "Text"),
    (3, "FreeText"),
    (4, "Line"),
    (5, "Square"),
    (6, "Circle"),
    (7, "Polygon"),
    (8, "PolyLine"),
    (FPDF_ANNOT_HIGHLIGHT, "Highlight"),
    (10, "Underline"),
    (11, "Squiggly"),
    (12, "StrikeOut"),
    (13, "Stamp"),
    (14, "Caret"),
    (FPDF_ANNOT_INK, "Ink"),
    (17, "FileAttachment"),
];

pub fn subtype_name(subtype: c_int) -> Option<&'static str> {
    LISTED.iter().find(|(s, _)| *s == subtype).map(|(_, n)| *n)
}

/// An open annotation handle, closed on drop.
struct Annot<'p> {
    page: &'p Page<'p>,
    h: FPDF_ANNOTATION,
}

impl<'p> Annot<'p> {
    fn get(page: &'p Page<'p>, index: c_int) -> Option<Self> {
        let h = unsafe { page.b().FPDFPage_GetAnnot(page.h, index) };
        (!h.is_null()).then_some(Self { page, h })
    }

    fn create(page: &'p Page<'p>, subtype: c_int) -> Result<Self, String> {
        let h = unsafe { page.b().FPDFPage_CreateAnnot(page.h, subtype) };
        if h.is_null() {
            return Err("Could not create a comment".into());
        }
        Ok(Self { page, h })
    }

    fn string(&self, key: &str) -> String {
        let b = self.page.b();
        read_utf16(|buf, len| unsafe { b.FPDFAnnot_GetStringValue(self.h, key, buf, len) })
    }

    fn set_string(&self, key: &str, value: &str) {
        let wide = to_wide(value);
        unsafe { self.page.b().FPDFAnnot_SetStringValue(self.h, key, wide.as_ptr()) };
    }

    fn has_key(&self, key: &str) -> bool {
        unsafe { self.page.b().FPDFAnnot_HasKey(self.h, key) != 0 }
    }

    /// Index of the annotation this one points to with `key` (`/Popup`, `/IRT`).
    fn linked_index(&self, key: &str) -> Option<u32> {
        let b = self.page.b();
        let linked = unsafe { b.FPDFAnnot_GetLinkedAnnot(self.h, key) };
        if linked.is_null() {
            return None;
        }
        let i = unsafe { b.FPDFPage_GetAnnotIndex(self.page.h, linked) };
        unsafe { b.FPDFPage_CloseAnnot(linked) };
        u32::try_from(i).ok()
    }

    fn set_rect(&self, (l, b, r, t): (f32, f32, f32, f32)) {
        let rect = FS_RECTF { left: l, top: t, right: r, bottom: b };
        unsafe { self.page.b().FPDFAnnot_SetRect(self.h, &rect) };
    }
}

impl Drop for Annot<'_> {
    fn drop(&mut self) {
        unsafe { self.page.b().FPDFPage_CloseAnnot(self.h) };
    }
}

// ---------- listing ----------

/// Comments on pages `first .. first + count`. Stops early (returning fewer pages)
/// once the text listed reaches the per-request budget; the caller asks again from
/// the next page.
pub fn list(doc: &Doc, first: i32, count: i32) -> Result<Vec<PageAnnots>, String> {
    let total = doc.page_count();
    if first < 0 || first >= total || count < 1 {
        return Err("Page range is invalid".into());
    }
    let end = first.saturating_add(count.min(MAX_ANNOT_PAGES)).min(total);
    let mut out = Vec::new();
    let mut bytes = 0;
    for i in first..end {
        let page = list_page(doc, i);
        bytes += page.annots.iter().map(|a| a.contents.len() + a.author.len()).sum::<usize>();
        out.push(page);
        if bytes >= MAX_REQUEST_TEXT_BYTES {
            break;
        }
    }
    Ok(out)
}

/// Comments on one page. A page that cannot be loaded lists none.
fn list_page(doc: &Doc, page_index: i32) -> PageAnnots {
    let mut out = PageAnnots { page_index, annots: Vec::new(), more: 0 };
    let Ok(page) = doc.page(page_index) else { return out };
    let b = page.b();
    let display = page.display_matrix();
    let n = unsafe { b.FPDFPage_GetAnnotCount(page.h) }.clamp(0, 100_000);
    let mut text_bytes = 0;
    for i in 0..n {
        let Some(a) = Annot::get(&page, i) else { continue };
        let Some(subtype) = subtype_name(unsafe { b.FPDFAnnot_GetSubtype(a.h) }) else { continue };
        let flags = unsafe { b.FPDFAnnot_GetFlags(a.h) };
        if flags & (FPDF_ANNOT_FLAG_HIDDEN | FPDF_ANNOT_FLAG_NOVIEW | FPDF_ANNOT_FLAG_INVISIBLE) != 0 {
            continue;
        }
        if out.annots.len() >= MAX_LISTED_PER_PAGE || text_bytes >= MAX_PAGE_TEXT_BYTES {
            out.more += 1;
            continue;
        }
        let mut r = FS_RECTF { left: 0.0, top: 0.0, right: 0.0, bottom: 0.0 };
        unsafe { b.FPDFAnnot_GetRect(a.h, &mut r) };
        let (x0, y0, x1, y1) = display.apply_rect(r.left, r.bottom, r.right, r.top);
        let (contents, truncated) = cut(a.string("Contents"), MAX_ANNOT_TEXT);
        let (author, _) = cut(a.string("T"), 256);
        let date = match a.string("M") {
            m if !m.is_empty() => m,
            _ => a.string("CreationDate"),
        };
        let (date, _) = cut(date, 64);
        let (mut cr, mut cg, mut cb, mut ca): (c_uint, c_uint, c_uint, c_uint) = (0, 0, 0, 0);
        let has_color = unsafe {
            b.FPDFAnnot_GetColor(a.h, FPDFANNOT_COLORTYPE_COLOR, &mut cr, &mut cg, &mut cb, &mut ca)
        } != 0;
        text_bytes += contents.len() + author.len();
        out.annots.push(AnnotInfo {
            index: i as u32,
            subtype: subtype.into(),
            rect: rect_of(x0, y0, x1, y1),
            contents,
            truncated,
            author,
            date,
            color: has_color.then(|| [cr.min(255) as u8, cg.min(255) as u8, cb.min(255) as u8]),
            popup: a.linked_index("Popup"),
            in_reply_to: a.linked_index("IRT"),
        });
    }
    out
}

fn round2(v: f32) -> f32 {
    (v * 100.0).round() / 100.0
}

fn rect_of(x0: f32, y0: f32, x1: f32, y1: f32) -> Rect {
    Rect { x: round2(x0), y: round2(y0), width: round2(x1 - x0), height: round2(y1 - y0) }
}

/// Cuts `s` to at most `max` characters; true when something was cut.
pub fn cut(s: String, max: usize) -> (String, bool) {
    match s.char_indices().nth(max) {
        Some((at, _)) => (s[..at].to_string(), true),
        None => (s, false),
    }
}

// ---------- text characters ----------

/// Every character of a page with its box in display space, for selection.
pub fn text_chars(doc: &Doc, page_index: i32) -> Result<TextChars, String> {
    let page = doc.page(page_index)?;
    let tp = page.text_page()?;
    let b = page.b();
    let display = page.display_matrix();
    let n = unsafe { b.FPDFText_CountChars(tp.h) }.clamp(0, MAX_TEXT_CHARS);
    let mut out = TextChars {
        codes: Vec::with_capacity(n as usize),
        boxes: Vec::with_capacity(n as usize * 4),
    };
    for i in 0..n {
        let u = unsafe { b.FPDFText_GetUnicode(tp.h, i) };
        out.codes.push(u16::try_from(u).unwrap_or(0xFFFD));
        let mut r = FS_RECTF { left: 0.0, top: 0.0, right: 0.0, bottom: 0.0 };
        let real = unsafe { b.FPDFText_IsGenerated(tp.h, i) } == 0
            && unsafe { b.FPDFText_GetLooseCharBox(tp.h, i, &mut r) } != 0;
        let (x0, y0, x1, y1) = if real {
            display.apply_rect(r.left, r.bottom, r.right, r.top)
        } else {
            (0.0, 0.0, 0.0, 0.0)
        };
        let rect = rect_of(x0, y0, x1, y1);
        out.boxes.extend([rect.x, rect.y, rect.width, rect.height]);
    }
    Ok(out)
}

// ---------- writing ----------

/// Plain text safe to write into a PDF string: no control characters except line
/// breaks and tabs, and `\r\n` and `\r` folded to `\n`.
pub fn clean_text(s: &str) -> String {
    s.replace("\r\n", "\n")
        .replace('\r', "\n")
        .chars()
        .filter(|&c| !c.is_control() || c == '\n' || c == '\t')
        .collect()
}

/// Rich text (`/RC`) holding the same plain text, for annotations that already have
/// one: viewers prefer `/RC` over `/Contents`, so a stale one would show the old text.
pub fn rich_text(plain: &str) -> String {
    let mut body = String::new();
    for line in plain.split('\n') {
        body.push_str("<p>");
        for c in line.chars() {
            match c {
                '&' => body.push_str("&amp;"),
                '<' => body.push_str("&lt;"),
                '>' => body.push_str("&gt;"),
                '"' => body.push_str("&quot;"),
                _ => body.push(c),
            }
        }
        body.push_str("</p>");
    }
    format!(
        "<?xml version=\"1.0\"?><body xmlns=\"http://www.w3.org/1999/xhtml\" \
         xmlns:xfa=\"http://www.xfa.org/schema/xfa-data/1.0/\" xfa:APIVersion=\"Acrobat:11.0.0\" \
         xfa:spec=\"2.0.2\">{body}</body>"
    )
}

/// Slack allowed past the page edge, in points (rounding in the UI).
const EDGE_SLACK: f32 = 1.0;

/// True when the display-space box `(x0, y0, x1, y1)` lies on a page of display size
/// `(w, h)`.
pub fn on_page((x0, y0, x1, y1): (f32, f32, f32, f32), (w, h): (f32, f32)) -> bool {
    x0 >= -EDGE_SLACK && y0 >= -EDGE_SLACK && x1 <= w + EDGE_SLACK && y1 <= h + EDGE_SLACK
}

/// Display-space bounds of a new comment's geometry (ink without its stroke width).
pub fn shape_bounds(shape: &AnnotShape) -> (f32, f32, f32, f32) {
    let mut acc: Option<(f32, f32, f32, f32)> = None;
    let mut add = |x: f32, y: f32| {
        acc = Some(match acc {
            None => (x, y, x, y),
            Some((l, t, r, b)) => (l.min(x), t.min(y), r.max(x), b.max(y)),
        });
    };
    match shape {
        AnnotShape::Note { x, y } => {
            add(*x, *y);
            add(x + NOTE_SIZE, y + NOTE_SIZE);
        }
        AnnotShape::Highlight { rects } => {
            for r in rects {
                add(r.x, r.y);
                add(r.x + r.width, r.y + r.height);
            }
        }
        AnnotShape::Ink { strokes, .. } => strokes.iter().flatten().for_each(|p| add(p.x, p.y)),
    }
    acc.unwrap_or_default()
}

/// Changes annotations already on the page, in place. Must run before any
/// annotation is removed, because indices refer to the original page. `display`
/// maps page space to display space; `size` is the page's display size.
pub fn apply_changes(page: &Page, display: &Matrix, size: (f32, f32), changes: &[AnnotChange]) -> Result<(), String> {
    let count = unsafe { page.b().FPDFPage_GetAnnotCount(page.h) }.max(0) as u32;
    for c in changes {
        if c.index >= count {
            continue;
        }
        let Some(a) = Annot::get(page, c.index as c_int) else { continue };
        if let Some(contents) = &c.contents {
            let text = clean_text(contents);
            a.set_string("Contents", &text);
            if a.has_key("RC") {
                a.set_string("RC", &rich_text(&text));
            }
        }
        if let Some(at) = c.at {
            // Only notes move: markup is tied to the text under it.
            if unsafe { page.b().FPDFAnnot_GetSubtype(a.h) } != FPDF_ANNOT_TEXT {
                return Err("Only notes can be moved".into());
            }
            let mut r = FS_RECTF { left: 0.0, top: 0.0, right: 0.0, bottom: 0.0 };
            unsafe { page.b().FPDFAnnot_GetRect(a.h, &mut r) };
            let (x0, y0, x1, y1) = display.apply_rect(r.left, r.bottom, r.right, r.top);
            let moved = (at.x, at.y, at.x + (x1 - x0), at.y + (y1 - y0));
            if !on_page(moved, size) {
                return Err("A comment lies outside the page".into());
            }
            let inv = display.invert().ok_or("Page has an invalid size")?;
            let mut bounds = Bounds::default();
            bounds.add(inv.apply(moved.0, moved.1));
            bounds.add(inv.apply(moved.2, moved.3));
            a.set_rect(bounds.get());
        }
        a.set_string("M", &c.date);
    }
    Ok(())
}

/// Adds the annotations created in the app. `inv` maps display space to page space;
/// `size` is the page's display size (every comment must lie on the page).
pub fn add(page: &Page, inv: &Matrix, size: (f32, f32), list: &[NewAnnot]) -> Result<(), String> {
    let b = page.b();
    for n in list {
        n.validate()?;
        if !on_page(shape_bounds(&n.shape), size) {
            return Err("A comment lies outside the page".into());
        }
        let (subtype, flags) = match n.shape {
            AnnotShape::Note { .. } => (
                FPDF_ANNOT_TEXT,
                FPDF_ANNOT_FLAG_PRINT | FPDF_ANNOT_FLAG_NOZOOM | FPDF_ANNOT_FLAG_NOROTATE,
            ),
            AnnotShape::Highlight { .. } => (FPDF_ANNOT_HIGHLIGHT, FPDF_ANNOT_FLAG_PRINT),
            AnnotShape::Ink { .. } => (FPDF_ANNOT_INK, FPDF_ANNOT_FLAG_PRINT),
        };
        let a = Annot::create(page, subtype)?;
        let mut bounds = Bounds::default();
        match &n.shape {
            AnnotShape::Note { x, y } => {
                bounds.add(inv.apply(*x, *y));
                bounds.add(inv.apply(x + NOTE_SIZE, y + NOTE_SIZE));
            }
            AnnotShape::Highlight { rects } => {
                for r in rects {
                    // Corners in the order viewers expect: top-left, top-right,
                    // bottom-left, bottom-right (as seen on the page).
                    let p = [
                        inv.apply(r.x, r.y),
                        inv.apply(r.x + r.width, r.y),
                        inv.apply(r.x, r.y + r.height),
                        inv.apply(r.x + r.width, r.y + r.height),
                    ];
                    p.iter().for_each(|&q| bounds.add(q));
                    let quad = FS_QUADPOINTSF {
                        x1: p[0].0,
                        y1: p[0].1,
                        x2: p[1].0,
                        y2: p[1].1,
                        x3: p[2].0,
                        y3: p[2].1,
                        x4: p[3].0,
                        y4: p[3].1,
                    };
                    unsafe { b.FPDFAnnot_AppendAttachmentPoints(a.h, &quad) };
                }
            }
            AnnotShape::Ink { strokes, width } => {
                for s in strokes {
                    let pts: Vec<FS_POINTF> = s
                        .iter()
                        .map(|p| {
                            let (x, y) = inv.apply(p.x, p.y);
                            bounds.add((x, y));
                            FS_POINTF { x, y }
                        })
                        .collect();
                    unsafe { b.FPDFAnnot_AddInkStroke(a.h, pts.as_ptr(), pts.len()) };
                }
                unsafe { b.FPDFAnnot_SetBorder(a.h, 0.0, 0.0, *width) };
            }
        }
        a.set_rect(bounds.get());
        let [r, g, bl] = n.color;
        let alpha = (n.opacity.clamp(0.0, 1.0) * 255.0).round() as c_uint;
        unsafe {
            b.FPDFAnnot_SetColor(a.h, FPDFANNOT_COLORTYPE_COLOR, r as c_uint, g as c_uint, bl as c_uint, alpha);
            b.FPDFAnnot_SetFlags(a.h, flags);
        }
        a.set_string("NM", &n.id);
        a.set_string("M", &n.date);
        a.set_string("CreationDate", &n.date);
        let contents = clean_text(&n.contents);
        if !contents.is_empty() {
            a.set_string("Contents", &contents);
        }
        let author = clean_text(&n.author);
        if !author.is_empty() {
            a.set_string("T", &author);
        }
    }
    Ok(())
}

/// Running bounds of page-space points: (left, bottom, right, top).
#[derive(Default)]
struct Bounds(Option<(f32, f32, f32, f32)>);

impl Bounds {
    fn add(&mut self, (x, y): (f32, f32)) {
        self.0 = Some(match self.0 {
            None => (x, y, x, y),
            Some((l, b, r, t)) => (l.min(x), b.min(y), r.max(x), t.max(y)),
        });
    }

    fn get(&self) -> (f32, f32, f32, f32) {
        self.0.unwrap_or_default()
    }
}

